package vn.svframe.svframelib.script.condition;import vn.svframe.svframelib.skill.SkillMetadata;import vn.svframe.svframelib.util.configobject.EmptyConfigObject;import vn.svframe.mythiclibfabric.MythicLibFabricMod;import java.util.Map;public class RawCondition extends Condition{private final String raw;public RawCondition(String raw){super(new EmptyConfigObject());this.raw=raw;}public boolean isMet(SkillMetadata metadata){return MythicLibFabricMod.castInline(Map.of("conditions",java.util.List.of(raw),"mechanics",java.util.List.of()),vn.svframe.svframelib.skill.SkillMetadataContextBridge.context(metadata));}}